  '\\nDonation type not found\', \'en\']]' => '\\nТип пожертвования не найден\', \'ru\']]',
  '\\nEdit donation type\\n' => '\\nИзменить тип пожертвования\\n',
  'Basics' => 'Основы',
  'Title' => 'Название',
