  '\\nAddress name\\n' => '\\nНазвание адреса\\n',
  '\\ne.g. Home, Office\\n' => '\\ne.g. Дом, офис\\n',
  'Save address' => 'Сохранить адрес',
  '\\nSaved address\\n' => '\\nСохраненный адрес\\n',
  '\\nWrite the new address below; it is saved to your address book with the order.\\n' => '\\nНапишите новый адрес ниже; он сохраняется в вашей адресной книге вместе с заказом.\\n',
  '\\nManage addresses\\n' => '\\nУправление адресами\\n',
