  '[[\'donor\', \'en\']]' . chr(0) . '[[\'donors\', \'en\']]' => '[[\'донор\', \'эн\']]' . chr(0) . '[[\'доноры\', \'en\']]' . chr(0) . '[[\'доноры\', \'en\']]',
  '[[\'day left\', \'en\']]' . chr(0) . '[[\'days left\', \'en\']]' => '[[\'остался день\', \'эн\']]' . chr(0) . '[[\'осталось дней\', \'en\']]' . chr(0) . '[[\'осталось дней\', \'en\']]',
  '\\nEnter a name.\\n' => '\\nВведите имя.\\n',
