  '\\nMark completed\\n' => '\\nОтметить как завершенное\\n',
  '\\nYour gift on behalf of%1$sis completed. Thank you. Code:%2$s\\n' => '\\nВаш подарок от имени%1$sзавершен. Спасибо. Код:%2$s\\n',
  'Menu name' => 'Название меню',
  '\\nPage title\\n' => '\\nЗаголовок страницы\\n',
