  'Repeats' => '\\nПовторяется\\n',
  'Names (one per share)' => '[[\'Имена (по одному на каждую акцию)\\n',
  'Design' => '\\nДизайн\\n',
  'Name on the certificate' => '\\nИмя в сертификате\\n',
  'Sent to' => '\\nОтправлено\\n',
  'copy to me' => '\\nкопируй мне\\n',
